tMessage());return false;}}public static function delete($a){if(!self::ensureTables()){return false;}try{$b=DB::pdo();$b->prepare('DELETE FROM `'.self::LOG_TABLE.'` WHERE `token_id` = :id')->execute(array(':id'=>(int)$a));return $b->prepare('DELETE FROM `'.self::TABLE.'` WHERE `id` = :id')->execute(array(':id'=>(int)$a));}catch(\Throwable $c){error_log('[ApiToken::delete] '.$c->getMessage());return false;}}public static function getLogs($a=null,$b=null,$c=null,$d=1,$e=50){$f=array('total'=>0,'page'=>(int)$d,'items'=>array());if(!self::ensureTables()){return $f;}try{$g=DB::pdo();$d=max(1,(int)$d);$h=max(1,(int)$e);$i=($d-1)*$h;$j='1=1';$k=array();if($a){$j.=' AND `token_id` = :tid';$k[':tid']=(int)$a;}if($b){$j.=' AND `created_at` >= :sd';$k[':sd']=$b.' 00:00:00';}if($c){$j.=' AND `created_at` <= :ed';$k[':ed']=$c.' 23:59:59';}$l=$g->prepare('SELECT COUNT(*) AS n FROM `'.self::LOG_TABLE.'` WHERE '.$j);$l->execute($k);$m=$l->fetch();$f['total']=$m?(int)$m['n']:0;$n='SELECT * FROM `'.self::LOG_TABLE.'` WHERE '.$j.' ORDER BY `id` DESC LIMIT '.$i.','.$h;$l=$g->prepare($n);$l->execute($k);$f['items']=$l->fetchAll();return $f;}catch(\Throwable $o){error_log('[ApiToken::getLogs] '.$o->getMessage());return $f;}}public static function getStats(){$a=array('total_tokens'=>0,'active_tokens'=>0,'today_calls'=>0,'yesterday_calls'=>0,'total_calls'=>0,'success_rate'=>0);if(!self::ensureTables()){return $a;}try{$b=DB::pdo();foreach(array('total_tokens'=>'SELECT COUNT(*) AS n FROM `'.self::TABLE.'`','active_tokens'=>'SELECT COUNT(*) AS n FROM `'.self::TABLE.'` WHERE `status`=1','today_calls'=>'SELECT COUNT(*) AS n FROM `'.self::LOG_TABLE.'` WHERE `created_at` >= CURDATE() AND `created_at` < DATE_ADD(CURDATE(),INTERVAL 1 DAY)','yesterday_calls'=>'SELECT COUNT(*) AS n FROM `'.self::LOG_TABLE.'` WHERE `created_at` >= DATE_SUB(CURDATE(),INTERVAL 1 DAY) AND `created_at` < CURDATE()','total_calls'=>'SELECT COUNT(*) AS n FROM `'.self::LOG_TABLE.'`',)as $c=>$d){$e=$b->query($d)->fetch();$a[$c]=$e?(int)$e['n']:0;}if($a['total_calls']>0){$f=$b->prepare('SELECT COUNT(*) AS n FROM `'.self::LOG_TABLE.'` WHERE `response_code` >= 200 AND `response_code` < 400');$f->execute();$g=$f->fetch();$h=$g?(int)$g['n']:0;$a['success_rate']=round(($h/$a['total_calls'])*100,1);}return $a;}catch(\Throwable $i){error_log('[ApiToken::getStats] '.$i->getMessage());return $a;}}public static function todayUsageMap(){$a=array();if(!self::ensureTables()){return $a;}try{$b=DB::pdo()->query('SELECT `token_id`, COUNT(*) AS n FROM `'.self::LOG_TABLE.'`
